"""Regression tests for the TLS material generated by traefik/scripts/certs.sh (real openssl)."""

import os
import pathlib
import shutil
import subprocess
import tempfile
import unittest


CERTS_SCRIPT = pathlib.Path(__file__).parents[2] / "traefik" / "scripts" / "certs.sh"
DOMAIN = "lab.example.test"


def openssl(*args, cwd, input_text=None):
    return subprocess.run(
        ["openssl", *args], cwd=cwd, input=input_text, text=True, capture_output=True, check=True
    ).stdout


class CertsScriptTests(unittest.TestCase):
    def setUp(self):
        self.directory = tempfile.TemporaryDirectory()
        self.addCleanup(self.directory.cleanup)
        self.root = pathlib.Path(self.directory.name)
        (self.root / "traefik" / "scripts").mkdir(parents=True)
        shutil.copy2(CERTS_SCRIPT, self.root / "traefik" / "scripts" / "certs.sh")
        self.certs = self.root / "traefik" / "certs"

    def run_certs(self, mode, domain=DOMAIN, regen=False):
        environment = os.environ.copy()
        environment.update({"DOMAIN": domain, "TLS_MODE": mode, "TLS_CSR_REGEN": "true" if regen else "false"})
        return subprocess.run(
            ["bash", str(self.root / "traefik" / "scripts" / "certs.sh")],
            cwd=self.root, env=environment, text=True, capture_output=True, check=False,
        )

    def sans(self, name):
        return openssl("x509", "-in", str(self.certs / name), "-noout", "-ext", "subjectAltName", cwd=self.root)

    def fingerprint(self, name):
        return openssl("x509", "-in", str(self.certs / name), "-noout", "-fingerprint", "-sha256", cwd=self.root)

    def verifies(self, cert, ca):
        return subprocess.run(
            # -x509_strict matches the strict verification Python >= 3.13 applies by default.
            ["openssl", "verify", "-x509_strict", "-CAfile", str(self.certs / ca), str(self.certs / cert)],
            capture_output=True, check=False,
        ).returncode == 0

    def make_user_ca(self):
        """Simulate the operator's own certificate authority, outside traefik/certs."""
        ca_dir = self.root / "user-ca"
        ca_dir.mkdir()
        openssl("genpkey", "-algorithm", "EC", "-pkeyopt", "ec_paramgen_curve:P-256", "-out", "ca.key", cwd=ca_dir)
        openssl("req", "-x509", "-new", "-key", "ca.key", "-days", "30", "-subj", "/CN=Operator Root CA",
                "-addext", "basicConstraints=critical,CA:TRUE", "-addext", "keyUsage=critical,keyCertSign",
                "-out", "ca.crt", cwd=ca_dir)
        return ca_dir

    def sign_csr(self, ca_dir, csr, sans, key_ids=True):
        ext = ca_dir / "ext.cnf"
        # "none" because OpenSSL 3.x otherwise adds key identifiers on its own.
        ids = ("subjectKeyIdentifier=hash\nauthorityKeyIdentifier=keyid:always\n" if key_ids
               else "subjectKeyIdentifier=none\nauthorityKeyIdentifier=none\n")
        ext.write_text(f"subjectAltName={sans}\nbasicConstraints=CA:FALSE\nextendedKeyUsage=serverAuth\n{ids}")
        openssl("x509", "-req", "-in", str(csr), "-CA", "ca.crt", "-CAkey", "ca.key", "-set_serial", "1",
                "-days", "20", "-extfile", "ext.cnf", "-out", "signed.crt", cwd=ca_dir)
        return ca_dir / "signed.crt"

    def test_internal_mode_issues_split_chains(self):
        result = self.run_certs("internal")
        self.assertEqual(result.returncode, 0, result.stderr)
        for name in ("internal-ca.crt", "internal-ca.key", "vault.crt", "vault.key", "tls.crt", "tls.key", "ca.crt", "trust.crt"):
            self.assertTrue((self.certs / name).is_file(), name)
        self.assertIn(f"DNS:{DOMAIN}, DNS:*.{DOMAIN}", self.sans("tls.crt"))
        self.assertIn("DNS:vault, DNS:localhost, IP Address:127.0.0.1", self.sans("vault.crt"))
        self.assertTrue(self.verifies("tls.crt", "internal-ca.crt"))
        self.assertTrue(self.verifies("vault.crt", "internal-ca.crt"))
        self.assertEqual((self.certs / "ca.crt").read_text(), (self.certs / "internal-ca.crt").read_text())

    def test_internal_mode_is_idempotent_and_follows_domain_changes(self):
        self.assertEqual(self.run_certs("internal").returncode, 0)
        ca, tls = self.fingerprint("internal-ca.crt"), self.fingerprint("tls.crt")
        self.assertEqual(self.run_certs("internal").returncode, 0)
        self.assertEqual(self.fingerprint("tls.crt"), tls)

        self.assertEqual(self.run_certs("internal", domain="other.example.test").returncode, 0)
        self.assertEqual(self.fingerprint("internal-ca.crt"), ca)
        self.assertNotEqual(self.fingerprint("tls.crt"), tls)
        self.assertIn("DNS:other.example.test, DNS:*.other.example.test", self.sans("tls.crt"))

    def test_custom_mode_generates_p256_csr_and_waits(self):
        result = self.run_certs("custom")
        self.assertEqual(result.returncode, 2, result.stderr)
        self.assertIn("custom.csr", result.stdout)
        csr = openssl("req", "-in", str(self.certs / "custom.csr"), "-noout", "-text", cwd=self.root)
        self.assertIn(f"DNS:{DOMAIN}, DNS:*.{DOMAIN}", csr)
        self.assertIn("prime256v1", csr)
        self.assertTrue((self.certs / "vault.crt").is_file())

    def test_csr_request_leaves_served_internal_certificate_untouched(self):
        self.assertEqual(self.run_certs("internal").returncode, 0)
        served = self.fingerprint("tls.crt"), (self.certs / "tls.key").read_text()
        result = self.run_certs("internal", regen=True)
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertTrue((self.certs / "custom.csr").is_file())
        self.assertEqual((self.fingerprint("tls.crt"), (self.certs / "tls.key").read_text()), served)

    def test_custom_mode_installs_certificate_signed_by_operator_ca(self):
        self.assertEqual(self.run_certs("internal").returncode, 0)
        self.assertEqual(self.run_certs("internal", regen=True).returncode, 0)
        ca_dir = self.make_user_ca()
        signed = self.sign_csr(ca_dir, self.certs / "custom.csr", f"DNS:{DOMAIN},DNS:*.{DOMAIN}")
        shutil.copy2(signed, self.certs / "custom.crt")
        shutil.copy2(ca_dir / "ca.crt", self.certs / "custom-ca.crt")

        result = self.run_certs("custom")
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertIn("Custom ingress certificate validated", result.stdout)
        self.assertIn("expires within 30 days", result.stdout)
        self.assertEqual((self.certs / "tls.crt").read_text(), signed.read_text())
        self.assertEqual((self.certs / "tls.key").read_text(), (self.certs / "custom.key").read_text())
        self.assertEqual((self.certs / "ca.crt").read_text(), (ca_dir / "ca.crt").read_text())
        trust = (self.certs / "trust.crt").read_text()
        self.assertIn((self.certs / "internal-ca.crt").read_text(), trust)
        self.assertIn((ca_dir / "ca.crt").read_text(), trust)

        # Switching back to internal reissues an internal ingress certificate.
        self.assertEqual(self.run_certs("internal").returncode, 0)
        self.assertTrue(self.verifies("tls.crt", "internal-ca.crt"))

    def test_custom_mode_rejects_wrong_names_and_foreign_keys(self):
        self.assertEqual(self.run_certs("custom").returncode, 2)
        ca_dir = self.make_user_ca()
        shutil.copy2(ca_dir / "ca.crt", self.certs / "custom-ca.crt")

        wrong_names = self.sign_csr(ca_dir, self.certs / "custom.csr", f"DNS:{DOMAIN}")
        shutil.copy2(wrong_names, self.certs / "custom.crt")
        result = self.run_certs("custom")
        self.assertEqual(result.returncode, 1)
        self.assertIn("subjectAltName", result.stderr)

        openssl("genpkey", "-algorithm", "EC", "-pkeyopt", "ec_paramgen_curve:P-256", "-out", "other.key", cwd=ca_dir)
        openssl("req", "-new", "-key", "other.key", "-subj", f"/CN={DOMAIN}", "-out", "other.csr", cwd=ca_dir)
        foreign = self.sign_csr(ca_dir, ca_dir / "other.csr", f"DNS:{DOMAIN},DNS:*.{DOMAIN}")
        shutil.copy2(foreign, self.certs / "custom.crt")
        result = self.run_certs("custom")
        self.assertEqual(result.returncode, 1)
        self.assertIn("does not match", result.stderr)
        self.assertFalse((self.certs / "tls.crt").exists())

    def test_custom_mode_rejects_certificate_failing_strict_checks(self):
        self.assertEqual(self.run_certs("custom").returncode, 2)
        ca_dir = self.make_user_ca()
        lax = self.sign_csr(ca_dir, self.certs / "custom.csr", f"DNS:{DOMAIN},DNS:*.{DOMAIN}", key_ids=False)
        shutil.copy2(lax, self.certs / "custom.crt")
        shutil.copy2(ca_dir / "ca.crt", self.certs / "custom-ca.crt")
        result = self.run_certs("custom")
        self.assertEqual(result.returncode, 1)
        self.assertIn("Authority Key Identifier", result.stderr)

    def test_acme_modes_keep_internal_vault_chain(self):
        result = self.run_certs("http-01")
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertTrue(self.verifies("vault.crt", "internal-ca.crt"))
        self.assertFalse((self.certs / "tls.crt").exists())
        self.assertEqual((self.certs / "ca.crt").read_text(), (self.certs / "internal-ca.crt").read_text())


if __name__ == "__main__":
    unittest.main()
